########## REG_IF_ID.v
//////////////////////////////////////////////////////////////////////////////////

module    REG_IF_ID(input clk,                                      //IF/ID Latch
                    input rst,
                    input EN,                                       //流水寄存器使能
                    input Data_stall,                               //数据竞争等待
                    input flush,                                    //控制竞争清除并等待
                    input [31:0] PCOUT,                             //指令存储器指针
                    input [31:0] IR,                                //指令存储器输出

                    output reg[31:0] IR_ID,                         //取指锁存
                    output reg[31:0] PCurrent_ID,                   //当前存在指令地址
                    output reg isFlushed
                );

//reg[31:0]PCurrent_ID,IR_ID;
    always @(posedge clk or posedge rst) begin
        if(rst) begin
            IR_ID <= 32'h00000013;
            PCurrent_ID <= 32'h00000000;
            isFlushed <= 0;
        end
        else if(EN) begin
            if(Data_stall) begin                        // 数据竞争：保持当前指令
                IR_ID <= IR_ID;
                PCurrent_ID <= PCurrent_ID;
                isFlushed <= isFlushed;
            end
            else if(flush) begin                        // 控制竞争/异常：插入 NOP
                IR_ID <= 32'h00000013;
                PCurrent_ID <= PCurrent_ID;
                isFlushed <= 1;
            end
            else begin
                IR_ID <= IR;
                PCurrent_ID <= PCOUT;
                isFlushed <= 0;
            end
        end
    end

