 1	`timescale 1ps/1ps
 2	
 3	module HazardDetectionUnit(
 4	    input clk,
 5	    input Branch_ID, rs1use_ID, rs2use_ID,
 6	    input[1:0] hazard_optype_ID,
 7	    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
 8	    output PC_EN_IF, reg_FD_stall, reg_FD_flush, reg_DE_flush,
 9	    output forward_ctrl_ls,
10	    output[1:0] forward_ctrl_A, forward_ctrl_B
11	);
12	
13	    reg[1:0] hazard_optype_EXE, hazard_optype_MEM;
14	    initial begin
15	        hazard_optype_EXE = 2'd0;
16	        hazard_optype_MEM = 2'd0;
17	    end
18	    always@(posedge clk) begin
19	        hazard_optype_MEM <= hazard_optype_EXE;
20	        hazard_optype_EXE <= hazard_optype_ID & {2{~reg_DE_flush}};
21	    end
22	
23	    localparam hazard_optype_ALU = 2'd1;
24	    localparam hazard_optype_LOAD = 2'd2;
25	    localparam hazard_optype_STORE = 2'd3;
26	
27	    // an instruction in EX / MEM only really writes a register when its optype is
28	    // ALU (result ready at the end of EX) or LOAD (result ready in MEM, this also
29	    // covers the CSR reads)
30	    wire ALU_EXE  = hazard_optype_EXE == hazard_optype_ALU;
31	    wire LOAD_EXE = hazard_optype_EXE == hazard_optype_LOAD;
32	    wire ALU_MEM  = hazard_optype_MEM == hazard_optype_ALU;
33	    wire LOAD_MEM = hazard_optype_MEM == hazard_optype_LOAD;
34	
35	    wire ID_is_store = hazard_optype_ID == hazard_optype_STORE;
36	
37	    wire rs1_hit_EXE = rs1use_ID & (rs1_ID != 5'b0) & (rs1_ID == rd_EXE);
38	    wire rs2_hit_EXE = rs2use_ID & (rs2_ID != 5'b0) & (rs2_ID == rd_EXE);
39	    wire rs1_hit_MEM = rs1use_ID & (rs1_ID != 5'b0) & (rs1_ID == rd_MEM);
40	    wire rs2_hit_MEM = rs2use_ID & (rs2_ID != 5'b0) & (rs2_ID == rd_MEM);
41	
42	    // An ALU result can be bypassed straight out of the EX stage, but the data of a
43	    // load (or CSR read) is only known one cycle later, so the ID stage has to wait.
44	    // A store only needs its rs2 value in the MEM stage, so it may proceed and take
45	    // the value from the load-store forwarding path instead.
46	    wire stall = LOAD_EXE & (rs1_hit_EXE | (rs2_hit_EXE & ~ID_is_store));
47	
48	    assign PC_EN_IF = ~stall;
49	    assign reg_FD_stall = stall;
50	    assign reg_FD_flush = Branch_ID & ~stall;
51	    assign reg_DE_flush = stall;
52	
53	    // 00: register file, 01: EX bypass, 10: MEM ALU result, 11: MEM load/CSR data
54	    assign forward_ctrl_A = (ALU_EXE & rs1_hit_EXE)  ? 2'b01 :
55	                            (LOAD_MEM & rs1_hit_MEM) ? 2'b11 :
56	                            (ALU_MEM & rs1_hit_MEM)  ? 2'b10 : 2'b00;
57	
58	    assign forward_ctrl_B = (ALU_EXE & rs2_hit_EXE)  ? 2'b01 :
59	                            (LOAD_MEM & rs2_hit_MEM) ? 2'b11 :
60	                            (ALU_MEM & rs2_hit_MEM)  ? 2'b10 : 2'b00;
61	
62	    // store data of the instruction in EX taken from the load in MEM
63	    assign forward_ctrl_ls = LOAD_MEM & (rs2_EXE != 5'b0) & (rs2_EXE == rd_MEM);
64	
65	endmodule

