    hazard_optype_MEM <= hazard_optype_EXE;
    hazard_optype_EXE <= hazard_optype_ID & {2{~reg_DE_flush}};
end

localparam hazard_optype_ALU = 2'd1;
localparam hazard_optype_LOAD = 2'd2;
localparam hazard_optype_STORE = 2'd3;

// an instruction in EX / MEM only really writes a register when its optype is
// ALU (result ready at the end of EX) or LOAD (result ready in MEM, this also
// covers the CSR reads)
wire ALU_EXE  = hazard_optype_EXE == hazard_optype_ALU;
wire LOAD_EXE = hazard_optype_EXE == hazard_optype_LOAD;
wire ALU_MEM  = hazard_optype_MEM == hazard_optype_ALU;
wire LOAD_MEM = hazard_optype_MEM == hazard_optype_LOAD;

wire ID_is_store = hazard_optype_ID == hazard_optype_STORE;

wire rs1_hit_EXE = rs1use_ID & (rs1_ID != 5'b0) & (rs1_ID == rd_EXE);
wire rs2_hit_EXE = rs2use_ID & (rs2_ID != 5'b0) & (rs2_ID == rd_EXE);
wire rs1_hit_MEM = rs1use_ID & (rs1_ID != 5'b0) & (rs1_ID == rd_MEM);
wire rs2_hit_MEM = rs2use_ID & (rs2_ID != 5'b0) & (rs2_ID == rd_MEM);

// An ALU result can be bypassed straight out of the EX stage, but the data of a
// load (or CSR read) is only known one cycle later, so the ID stage has to wait.
// A store only needs its rs2 value in the MEM stage, so it may proceed and take
// the value from the load-store forwarding path instead.
wire stall = LOAD_EXE & (rs1_hit_EXE | (rs2_hit_EXE & ~ID_is_store));

assign PC_EN_IF = ~stall;
assign reg_FD_stall = stall;
assign reg_FD_flush = Branch_ID & ~stall;
assign reg_DE_flush = stall;

// 00: register file, 01: EX bypass, 10: MEM ALU result, 11: MEM load/CSR data
assign forward_ctrl_A = (ALU_EXE & rs1_hit_EXE)  ? 2'b01 :
                        (LOAD_MEM & rs1_hit_MEM) ? 2'b11 :
                        (ALU_MEM & rs1_hit_MEM)  ? 2'b10 : 2'b00;

assign forward_ctrl_B = (ALU_EXE & rs2_hit_EXE)  ? 2'b01 :
                        (LOAD_MEM & rs2_hit_MEM) ? 2'b11 :
                        (ALU_MEM & rs2_hit_MEM)  ? 2'b10 : 2'b00;

// store data of the instruction in EX taken from the load in MEM
assign forward_ctrl_ls = LOAD_MEM & (rs2_EXE != 5'b0) & (rs2_EXE == rd_MEM);

