module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea, 
    output[31:0] douta,
    output [7:0] sim_uart_char_out,
    output sim_uart_char_valid,
    input[2:0] mem_u_b_h_w
);
    localparam SIZE = 256;
    localparam ADDR_LINE = $clog2(SIZE);
    localparam SIM_UART_ADDR = 32'h10000000;

    reg[7:0] data[0:SIZE-1];

    initial	begin
        $readmemh("ram.mem", data);
    end

    // the memory-mapped UART is not backed by the RAM array
    wire uart_hit = addra == SIM_UART_ADDR;
    wire in_range = ~(|addra[31:ADDR_LINE]);

    wire[ADDR_LINE-1:0] a0 = addra[ADDR_LINE-1:0];
    wire[ADDR_LINE-1:0] a1 = addra[ADDR_LINE-1:0] + 1'd1;
    wire[ADDR_LINE-1:0] a2 = addra[ADDR_LINE-1:0] + 2'd2;
    wire[ADDR_LINE-1:0] a3 = addra[ADDR_LINE-1:0] + 2'd3;

    wire word = mem_u_b_h_w[1];
    wire half = ~mem_u_b_h_w[1] & mem_u_b_h_w[0];
    wire byt  = ~mem_u_b_h_w[1] & ~mem_u_b_h_w[0];
    wire unsign = mem_u_b_h_w[2];

    // byte/halfword/word write, little endian
    always @(negedge clka) begin
        if (wea && in_range && !uart_hit) begin
            data[a0] <= dina[7:0];
            if (half | word) data[a1] <= dina[15:8];
            if (word) begin
                data[a2] <= dina[23:16];
                data[a3] <= dina[31:24];
            end
        end
    end

    wire[31:0] data_word = {data[a3], data[a2], data[a1], data[a0]};
    wire[15:0] data_half = {data[a1], data[a0]};
    wire[7:0]  data_byte = data[a0];

    wire[31:0] res_half = unsign ? {16'b0, data_half} : {{16{data_half[15]}}, data_half};
    wire[31:0] res_byte = unsign ? {24'b0, data_byte} : {{24{data_byte[7]}}, data_byte};

    assign douta = (uart_hit | ~in_range) ? 32'b0 :
                   {32{word}} & data_word |
                   {32{half}} & res_half  |
                   {32{byt }} & res_byte  ;

    // simulated UART: a store to SIM_UART_ADDR hands the low byte to the character
    // stream for one cycle and echoes it to the simulation console
    reg[7:0] uart_char;
    reg      uart_valid;

    initial begin
        uart_char  = 8'b0;
        uart_valid = 1'b0;
    end

    always @(negedge clka) begin
        if (wea && uart_hit) begin
            uart_char  <= dina[7:0];
            uart_valid <= 1'b1;
            $write("%c", dina[7:0]);
            $fflush();
        end
        else begin
            uart_valid <= 1'b0;
        end
    end

    assign sim_uart_char_valid = uart_valid;
    assign sim_uart_char_out = uart_char;
endmodule

