// TODO: implement — detect forwarding conditions and load-use hazards
// Compute rs1_forward_*, rs2_forward_*, load_stall, and assign outputs

assign PC_EN_IF = ~cmu_stall;
assign reg_FD_stall = 1'b0;
assign reg_FD_flush = 1'b0;
assign reg_DE_flush = 1'b0;

assign forward_ctrl_A = 2'b0;
assign forward_ctrl_B = 2'b0;

assign forward_ctrl_ls = 1'b0;

input.new_string:
// an instruction in EX / MEM only really writes a register when its optype is
// ALU (result ready at the end of EX) or LOAD (result ready in MEM)
wire ALU_EXE  = hazard_optype_EXE == hazard_optype_ALU;
wire LOAD_EXE = hazard_optype_EXE == hazard_optype_LOAD;
wire ALU_MEM  = hazard_optype_MEM == hazard_optype_ALU;
wire LOAD_MEM = hazard_optype_MEM == hazard_optype_LOAD;

wire ID_is_store = hazard_optype_ID == hazard_optype_STORE;

wire rs1_forward_EXE = rs1use_ID & (rs1_ID != 5'b0) & (rs1_ID == rd_EXE);
wire rs2_forward_EXE = rs2use_ID & (rs2_ID != 5'b0) & (rs2_ID == rd_EXE);
wire rs1_forward_MEM = rs1use_ID & (rs1_ID != 5'b0) & (rs1_ID == rd_MEM);
wire rs2_forward_MEM = rs2use_ID & (rs2_ID != 5'b0) & (rs2_ID == rd_MEM);

// An ALU result can be bypassed straight out of EX, but load data is only known
// one cycle later, so the ID stage has to wait. A store only needs its rs2 value
// in MEM, so it may proceed and use the load-store forwarding path instead.
wire load_stall = LOAD_EXE & (rs1_forward_EXE | (rs2_forward_EXE & ~ID_is_store));

// a cache miss freezes every stage; a load-use hazard only holds IF/ID
assign PC_EN_IF = ~cmu_stall & ~load_stall;
assign reg_FD_stall = load_stall;
assign reg_FD_flush = Branch_ID & ~load_stall;
assign reg_DE_flush = load_stall;

// 00: register file, 01: EX bypass, 10: MEM ALU result, 11: MEM load data
assign forward_ctrl_A = (ALU_EXE & rs1_forward_EXE)  ? 2'b01 :
                        (LOAD_MEM & rs1_forward_MEM) ? 2'b11 :
                        (ALU_MEM & rs1_forward_MEM)  ? 2'b10 : 2'b00;

assign forward_ctrl_B = (ALU_EXE & rs2_forward_EXE)  ? 2'b01 :
                        (LOAD_MEM & rs2_forward_MEM) ? 2'b11 :
                        (ALU_MEM & rs2_forward_MEM)  ? 2'b10 : 2'b00;

// store data of the instruction in EX taken from the load in MEM
assign forward_ctrl_ls = LOAD_MEM & (rs2_EXE != 5'b0) & (rs2_EXE == rd_MEM);

