// Directed test for the lab4 cache + CMU, driven by the provided sim/cmu_sim.v
// harness. sim/inst.v documents the expected cost of each access
// (read/write hit = 1 cycle, miss = 1+17, miss needing a dirty write-back =
// 1+17+17) and the expected total of 128 cycles for the 9 access sequence.
module tb_lab4_cmu;
    reg clk, rst;
    wire [7:0] clk_count, inst_count, hit_count;

    cmu_sim dut(.clk(clk),.rst(rst),
        .clk_count(clk_count),.inst_count(inst_count),.hit_count(hit_count));

    initial begin clk = 0; rst = 1; #4 rst = 0; end
    always #1 clk = ~clk;

    integer errors = 0;

    task check(input[31:0] got, input[31:0] want, input[8*32-1:0] what);
        begin
            if (got !== want) begin
                $display("MISMATCH %0s: got %0d expected %0d", what, got, want);
                errors = errors + 1;
            end
            else $display("ok %0s = %0d", what, got);
        end
    endtask

    // the sequence stops advancing once inst.v returns valid == 0
    initial begin
        #1200;
        $display("");
        // 18+18+1+1+18+18+1+35+18 = 128, per the annotations in sim/inst.v
        check(clk_count, 128, "total cycles");
        check(inst_count, 9, "accesses completed");
        // data[2] read hit, data[3] write hit, data[6] write hit
        check(hit_count, 3, "single cycle (hit) accesses");

        if (errors == 0) $display("LAB4 CMU TEST PASSED");
        else $display("LAB4 CMU TEST FAILED with %0d errors", errors);
        $finish;
    end
endmodule

